                                .HasComment("Prezzo unitario dell'articolo al momento del consumo.");

                            b1.Property<DateTime>("UpdatedAt")
                                .ValueGeneratedOnAdd()
                                .HasColumnType("timestamp with time zone")
                                .HasColumnName("updated_at")
                                .HasDefaultValueSql("now()")
                                .HasComment("Ultima modifica della riga.");

                            b1.Property<string>("VariantsDescription")
                                .HasMaxLength(255)
                                .HasColumnType("character varying(255)")
                                .HasColumnName("variants_description")
                                .HasComment("Varianti scelte in forma leggibile congelata; testo libero della riga-scontrino, non uno snapshot di un'entità modellata.");

                            b1.Property<decimal>("VariantsSurcharge")
                                .ValueGeneratedOnAdd()
                                .HasColumnType("numeric(12,2)")
                                .HasDefaultValue(0m)
                                .HasColumnName("variants_surcharge")
                                .HasComment("Somma dei sovrapprezzi delle varianti su questa riga, inclusa in line_total.");

                            b1.HasKey("Id")
                                .HasName("pk_payment_wallet_transaction_items");

                            b1.HasIndex("PropertyId")
                                .HasDatabaseName("ix_payment_wallet_transaction_items_property");

                            b1.HasIndex("SaleItemPublicId")
                                .HasDatabaseName("ix_payment_wallet_transaction_items_sale_item")
                                .HasFilter("sale_item_public_id IS NOT NULL");

                            b1.HasIndex("TransactionId")
                                .HasDatabaseName("ix_payment_wallet_transaction_items_transaction");

                            b1.ToTable("wallet_transaction_items", "payment", t =>
                                {
                                    t.HasComment("Articolo consumato pagato con un movimento di debito del borsellino (es. una consumazione al bar), congelato al momento del consumo.");
                                });

                            b1.WithOwner()
                                .HasForeignKey("TransactionId")
                                .HasConstraintName("fk_wallet_transaction_items_wallet_transactions_transaction_id");
                        });

                    b.Navigation("Items");

                    b.Navigation("ReversesTransaction");

                    b.Navigation("Wallet");
                });

            modelBuilder.Entity("Module.Payment.Domain.Entities.Charge", b =>
                {
                    b.Navigation("Refunds");
                });

            modelBuilder.Entity("Module.Payment.Domain.Entities.WalletAccount", b =>
                {
                    b.Navigation("Transactions");
                });
